const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const examples={writing:'Write a thoughtful email to a client about a project delay. Keep it honest, reassuring, and under 150 words.',reasoning:'Help me decide whether our small team should build a feature in-house or use an existing tool. Compare speed, cost, control, and long-term maintenance.',coding:'Write a Python function that removes duplicate items from a list while preserving their original order. Include a short explanation and tests.'};
$$('[data-example]').forEach(b=>b.addEventListener('click',()=>{$('#prompt').value=examples[b.dataset.example];$('#prompt').dispatchEvent(new Event('input'));$('#prompt').focus()}));
$('#prompt').addEventListener('input',()=>{$('#char-count').textContent=`${$('#prompt').value.length.toLocaleString()} / 6,000`;$('#form-error').textContent=''});
$('#clear-prompt').addEventListener('click',()=>{$('#prompt').value='';$('#prompt').dispatchEvent(new Event('input'));$('#prompt').focus()});
$('#budget').addEventListener('input',()=>$('#budget-value').textContent=`$${(Number($('#budget').value)/1000).toFixed(3)}`);
$('#reset-prefs').addEventListener('click',()=>{$('[name=priority][value=quality]').checked=true;$('#budget').value=25;$('#budget').dispatchEvent(new Event('input'));$('#region').value='all';$('#task-type').value='auto';updatePreview()});
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
$('.brand').addEventListener('click',e=>{e.preventDefault();showView('workspace')});
function showView(id){$$('.view').forEach(v=>v.classList.toggle('hidden',v.id!==id));$$('.nav-link').forEach(b=>{b.classList.toggle('active',b.dataset.view===id);if(b.dataset.view===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});window.scrollTo({top:0,behavior:'smooth'})}
const models=[
 {id:'sol',name:'GPT-6.1 Sol',provider:'OpenAI',origin:'us',tag:'Broad task coverage',input:2,output:10,time:13,quality:[90,91,96,92,94]},
 {id:'sonnet',name:'Sonnet 5.5',provider:'Anthropic',origin:'us',tag:'Writing and structure',input:2,output:10,time:12,quality:[96,95,91,94,93]},
 {id:'gemini',name:'Gemini 3.8 Flash',provider:'Google',origin:'us',tag:'Lightweight requests',input:.75,output:3.75,time:5,quality:[85,90,84,85,88]},
 {id:'deepseek',name:'DeepSeek V4.1 Flash',provider:'DeepSeek',origin:'china',tag:'Resource efficiency',input:.3,output:1.2,time:9,quality:[81,83,91,92,82]},
 {id:'qwen',name:'Qwen3.8 Max',provider:'Alibaba',origin:'china',tag:'Versatile text tasks',input:2,output:6,time:11,quality:[89,89,92,90,91]},
 {id:'glm',name:'GLM-5.3',provider:'Z.ai',origin:'china',tag:'Reasoning-oriented tasks',input:1.4,output:4.4,time:10,quality:[86,86,93,93,89]}
];
const enabled=new Set(models.map(m=>m.id)),taskNames=['Writing','Summarization','Reasoning','Coding','Synthesis'],priorityNames={quality:'Best quality',balanced:'A little of both',economy:'Lower cost'};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'$'+n.toFixed(4);
let running=false,runNumber=0,toastTimer;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2400)}
function classify(t){if(/\b(code|python|javascript|function|sql|typescript|debug|program|algorithm|regex)\b/i.test(t))return 3;if(/\b(summary|summarize|summarise|condense|key points|meeting notes)\b/i.test(t))return 1;if(/\b(synthesi[sz]e|synthesis|sources|research|documents|literature)\b/i.test(t))return 4;if(/\b(decide|decision|compare|calculate|math|solve|reason|whether|versus|in-house)\b/i.test(t))return 2;return 0}
function evaluate(prompt,priority,region,budget){const task=$('#task-type').value==='auto'?classify(prompt):Number($('#task-type').value),inputTokens=Math.ceil(prompt.length/3.6)+240,outputTokens=[260,320,550,700,600][task];const rows=models.map(m=>{const cost=(inputTokens*m.input+outputTokens*m.output)/1e6;const reason=!enabled.has(m.id)?'Disabled by you':region!=='all'&&m.origin!==region?'Provider preference':cost>budget?'Above your budget':'';const q=m.quality[task],w={quality:[.92,.04,.04],balanced:[.62,.23,.15],economy:[.35,.55,.10]}[priority];return {...m,cost,q,score:q*w[0]+(1-Math.min(cost/.012,1))*100*w[1]+(1-m.time/20)*100*w[2],reason,eligible:!reason}});const eligible=rows.filter(m=>m.eligible).sort((a,b)=>b.score-a.score);return{prompt,priority,region,budget,task,inputTokens,outputTokens,rows,winner:eligible[0],eligibleCount:eligible.length}}
function renderLibrary(){$('#model-library').innerHTML=models.map((m,i)=>`<article class="library-item"><div class="library-top"><span class="library-index">0${i+1}</span><label class="switch"><input type="checkbox" data-model="${m.id}" ${enabled.has(m.id)?'checked':''} aria-label="Include ${m.name} in routing"><span></span></label></div><p class="eyebrow">${m.provider} / ${m.origin==='us'?'U.S.':'CHINA'}</p><h2>${m.name}</h2><p class="profile-label">Illustrative profile: ${m.tag.toLowerCase()}</p><div class="model-tariff"><span>$${m.input.toFixed(2)} <small>input</small></span><span>$${m.output.toFixed(2)} <small>output</small></span></div><p class="price-note">USD per 1M tokens · proposal snapshot</p></article>`).join('');$$('[data-model]').forEach(c=>c.addEventListener('change',()=>{c.checked?enabled.add(c.dataset.model):enabled.delete(c.dataset.model);toast(`${enabled.size} of 6 models enabled`);updatePreview()}))}
renderLibrary();
$('#prompt').addEventListener('input',updatePreview);
$('#budget').addEventListener('input',updatePreview);
$('#region').addEventListener('change',updatePreview);
$('#task-type').addEventListener('change',updatePreview);
$$('[name=priority]').forEach(el=>el.addEventListener('change',updatePreview));
updatePreview();
$('#route-button').addEventListener('click',async()=>{if(running){runNumber++;finishRun();$('#route-status').textContent='Routing cancelled';$('#route-explanation').textContent='Adjust your outcome or preferences, then try again.';return}const prompt=$('#prompt').value.trim();if(!prompt){$('#form-error').textContent='Describe an outcome or choose an example to begin.';$('#prompt').focus();return}const r=evaluate(prompt,$('[name=priority]:checked').value,$('#region').value,Number($('#budget').value)/1000),token=++runNumber;running=true;$('#route-button').innerHTML='Cancel routing <span aria-hidden="true">×</span>';$('.routing-panel').classList.add('running');$$('.model-endpoints span').forEach(s=>s.classList.remove('chosen'));$('#results').classList.add('hidden');paintCandidates(r);const stages=[['Reading the outcome',`${taskNames[r.task]} task selected. Estimating the response length.`],['Checking your constraints',`${r.eligibleCount} models meet your current limits.`],['Weighing the options',`Comparing illustrative profiles with “${priorityNames[r.priority]}” priority.`],['Making the selection',r.winner?`${r.winner.name} has the highest demo routing score.`:'No model meets all the constraints.']];for(let i=0;i<stages.length;i++){if(token!==runNumber)return;$$('.steps span').forEach((s,j)=>{s.classList.toggle('current',j===i);s.classList.toggle('done',j<i)});$('#route-status').textContent=stages[i][0];$('#route-explanation').textContent=stages[i][1];await new Promise(done=>setTimeout(done,530))}if(token!==runNumber)return;finishRun();$$('.steps span').forEach(s=>{s.classList.remove('current');s.classList.add('done')});if(r.winner){$$('.model-endpoints span')[models.findIndex(m=>m.id===r.winner.id)].classList.add('chosen');$('#route-status').textContent='Choice explained';renderResult(r)}else{$('#route-status').textContent='Adjust a constraint';renderEmpty(r)}$('#results').classList.remove('hidden');$('#results').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})});
function finishRun(){running=false;$('.routing-panel').classList.remove('running');$('#route-button').innerHTML='Run the demo <span class="button-spark" aria-hidden="true">✳</span>'}
function renderEmpty(r){$('#results').innerHTML=`<div class="empty-result"><p class="eyebrow">NO ELIGIBLE MODELS</p><h2>One small adjustment.</h2><p>${enabled.size===0?'All six models are disabled. Enable a model in the library to continue.':'Your enabled models do not meet this budget and provider combination. Increase the budget or broaden the provider preference.'}</p><button class="primary-button" id="adjust-constraints">${enabled.size===0?'Open model library':'Adjust my constraints'}</button></div>`;$('#adjust-constraints').onclick=()=>{if(enabled.size===0)showView('library');else{$('#budget').focus();$('.preferences').scrollIntoView({behavior:'smooth',block:'center'})}}}
const samples=[
`Subject: A quick update on your project\n\nHi Alex,\n\nI wanted to let you know that we need a little more time to complete the final review. We’re moving delivery to next Wednesday so we can address the remaining details properly.\n\nI know this affects your plans, and I’m sorry for the disruption. I’ll send a progress update on Monday and flag any changes early. If there’s something you need sooner, please let me know so we can prioritize it.\n\nThank you for your patience,\nThe project team\n\nPrepared example. Replace the name, dates and commitments before use.`,
`A clear summary structure\n\nMain point\n[One sentence capturing the source’s central claim.]\n\nWhat matters\n1. The key decision or finding.\n2. The evidence supporting it.\n3. The uncertainty or missing information.\n\nNext action\n[Owner, action and date, when the source provides them.]\n\nThis is a prepared template. No source text has been summarized by a live model.`,
`A decision framework for a small team\n\nStart with the constraint that is hardest to reverse.\n\nUse an existing tool when speed matters most, the workflow is conventional, and your team can accept the vendor’s limits.\n\nBuild in-house when the capability is central to your advantage, requirements are unusual, and you can commit to maintenance after launch.\n\nBefore committing, compare a small prototype against one existing tool using the same task. Record setup time, recurring cost, gaps, and who will own maintenance.\n\nA useful next question: which option would still work if the person implementing it left the team?\n\nPrepared example for the build-or-buy decision. Adapt the criteria to your situation.`,
`A small, readable starting point\n\ndef unique_in_order(items):\n    result = []\n    for item in items:\n        if item not in result:\n            result.append(item)\n    return result\n\nassert unique_in_order([3, 1, 3, 2, 1]) == [3, 1, 2]\nassert unique_in_order([]) == []\n\nThis version also accepts unhashable values. Worst-case time is O(n²). For hashable values, list(dict.fromkeys(items)) offers a concise alternative.\n\nPrepared example for the duplicate-removal task. It does not execute or test code in your browser.`,
`A source-grounded synthesis structure\n\nShared findings\n[Where the supplied sources agree, with a reference for each claim.]\n\nPoints of disagreement\n[What differs, and whether methods, dates or scope explain it.]\n\nEvidence gaps\n[Questions the supplied sources cannot answer.]\n\nWorking conclusion\n[A conclusion proportional to the evidence, with uncertainty made explicit.]\n\nThis is a prepared template. A live synthesis needs a fixed source packet and citations to that packet.`
];
function renderResult(r){const m=r.winner,output=samples[r.task],explanation=r.priority==='quality'?`Its illustrative ${taskNames[r.task].toLowerCase()} profile gives it the strongest quality-weighted score among your eligible models.`:r.priority==='economy'?'Your lower-cost priority gives price more weight while retaining a quality component. This model leads that illustrative comparison.':'It offers the highest combined demo score for quality, estimated cost and completion time under your settings.';$('#results').innerHTML=`<div class="result-heading"><div><p class="eyebrow">03 / YOUR ROUTE, EXPLAINED</p><h2>A choice with a reason.</h2></div><span class="demo-badge">Simulated result</span></div><div class="request-receipt"><span>YOUR OUTCOME</span><p>${escape(r.prompt)}</p><small>${taskNames[r.task]} · ${priorityNames[r.priority]} · ${r.region==='all'?'U.S. + China':r.region==='us'?'U.S. providers':'Chinese providers'}</small></div><div class="result-grid"><div class="decision"><span class="selected-label">SELECTED FOR ${taskNames[r.task].toUpperCase()}</span><h3>${m.name}</h3><p class="selected-provider">${m.provider} / ${m.origin==='us'?'U.S.':'China'}</p><p>${explanation}</p><div class="runner-up">${comparisonReason(r)}</div><dl class="metrics"><div><dt>Estimated cost</dt><dd>${money(m.cost)}</dd></div><div><dt>Modeled time</dt><dd>~${m.time}s</dd></div><div><dt>Demo task fit</dt><dd>${m.q}<small>/100</small></dd></div></dl><p class="estimate-note">Illustrative estimates, not measured performance. Cost assumes ${r.inputTokens.toLocaleString()} input + ${r.outputTokens} output tokens, including a prompt allowance.</p><div class="constraint-receipt"><span>${priorityNames[r.priority]}</span><span>${r.eligibleCount} eligible models</span><span>Budget $${r.budget.toFixed(3)}</span></div><button id="compare-toggle" class="secondary-button" aria-expanded="false" aria-controls="comparison">Compare all six models <span aria-hidden="true">+</span></button></div><article class="response"><div class="response-heading"><span>SAMPLE RESPONSE</span><div><button id="copy-result" class="text-button">Copy</button><button id="download-result" class="text-button">Save .txt</button></div></div><p class="sample-warning">Prepared ${taskNames[r.task].toLowerCase()} example. This demo uses a prepared sample, not a generated answer to your request.</p><div class="response-content ${r.task===3?'code-output':''}">${escape(output)}</div></article></div><section id="comparison" class="comparison hidden"><h3>The alternatives, in the open.</h3><p>Illustrative fit and time. Budget and provider settings are applied before ranking.</p><div class="table-scroll"><table><thead><tr><th>Model</th><th>Demo fit</th><th>Est. cost</th><th>Modeled time</th><th>Eligibility</th></tr></thead><tbody>${[...r.rows].sort((a,b)=>Number(b.eligible)-Number(a.eligible)||b.score-a.score).map(x=>`<tr class="${x.id===m.id?'winner-row':''}"><th scope="row">${x.name}${x.id===m.id?'<small>Selected</small>':''}</th><td><span class="fit-bar"><i style="--fit:${x.q}%"></i></span> ${x.q}</td><td>${money(x.cost)}</td><td>~${x.time}s</td><td>${x.reason||'Eligible'}</td></tr>`).join('')}</tbody></table></div></section><div class="result-actions"><span>Curious how the choice changes? Try a different priority.</span><button id="back-to-compose" class="text-button">Adjust this outcome</button></div>`;
$('#compare-toggle').onclick=()=>{const open=$('#comparison').classList.toggle('hidden')===false;$('#compare-toggle').setAttribute('aria-expanded',String(open));$('#compare-toggle span').textContent=open?'−':'+'};$('#copy-result').onclick=async()=>{try{await navigator.clipboard.writeText(`ZeroPrompt prepared demo response\n\n${output}`);toast('Sample response copied')}catch{toast('Select and copy the response text; clipboard access is unavailable.')}};$('#download-result').onclick=()=>{const url=URL.createObjectURL(new Blob([`ZeroPrompt — prepared demo response\nSelected model: ${m.name} (simulated routing)\n\n${output}`],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='zeroprompt-sample.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#back-to-compose').onclick=()=>{$('#prompt').focus();$('.compose').scrollIntoView({behavior:'smooth',block:'start'})}}

function currentRoute(){return evaluate($('#prompt').value.trim(),$('[name=priority]:checked').value,$('#region').value,Number($('#budget').value)/1000)}
function paintCandidates(r){$$('.model-endpoints span').forEach((el,i)=>{const m=r.rows[i];el.classList.toggle('excluded',!m.eligible);el.classList.toggle('chosen',m.id===r.winner?.id);el.title=m.reason||'Eligible';el.dataset.reason=m.reason});$('.caption-number').textContent=String(r.eligibleCount).padStart(2,'0');$('.routing-caption p').innerHTML='Models eligible.<br>Selected around <strong>your task.</strong>'}
function comparisonReason(r){const next=r.rows.filter(x=>x.eligible&&x.id!==r.winner.id).sort((a,b)=>b.score-a.score)[0];if(!next)return 'Only one model meets your current settings.';const m=r.winner,delta=m.cost-next.cost;return `<strong>Compared with ${next.name}</strong><p>${delta<0?`${money(-delta)} less per demo request`:delta>0?`${money(delta)} more per demo request`:'The same estimated price'}, with ${Math.abs(m.q-next.q)} ${m.q>=next.q?'higher':'lower'} illustrative fit points. Your ${priorityNames[r.priority].toLowerCase()} preference determines the trade-off.</p>`}
function updatePreview(){if(running){runNumber++;finishRun();$$('.steps span').forEach(s=>s.classList.remove('current','done'))}const prompt=$('#prompt').value.trim();$('#task-hint').textContent=prompt?($('#task-type').value==='auto'?'Detected: '+taskNames[classify(prompt)]:'Your selection'):'Detected automatically';if(!prompt){$('#instant-preview').innerHTML='<span class="eyebrow">LIVE DEMO PREVIEW</span><h3>Your next choice starts here.</h3><p>Try an example, then adjust a priority to see the recommendation change.</p>';$$('.model-endpoints span').forEach(s=>s.classList.remove('chosen','excluded'));$('#route-status').textContent='Ready when you are';return}const r=currentRoute();paintCandidates(r);$('#instant-preview').innerHTML=r.winner?`<span class="eyebrow">CURRENT DEMO CHOICE / ${taskNames[r.task].toUpperCase()}</span><h3>${r.winner.name}</h3><p>${money(r.winner.cost)} estimated · ~${r.winner.time}s modeled · ${r.eligibleCount} eligible</p><div class="preview-reason">${comparisonReason(r)}</div>`:'<span class="eyebrow">NO ELIGIBLE MODELS</span><h3>Adjust a constraint.</h3><p>Increase your budget, change the provider preference, or enable a model in the library.</p>';$('#route-status').textContent='Preview updated';$('#route-explanation').textContent='The preview changes instantly. Run the demo to see the selection steps and a sample response.';if(!$('#results').classList.contains('hidden')){let note=$('#stale-result');if(!note){note=document.createElement('p');note.id='stale-result';note.className='stale-result';$('#results').prepend(note)}note.textContent='Your settings changed. This result belongs to the previous run; run the demo again to update it.'}}
